"use client";

import type { ReactNode } from "react";

type MotionProps = {
  children: ReactNode;
  className?: string;
  entrance?: string;
  delayMs?: number;
};

const PRESET = "atlas-reveal";
const REDUCED_MOTION = "fade";
const DEFAULT_DURATION = 520;

const ENTRANCE_TYPES: Record<string, string> = {
  "hero": "slide-up",
  "section": "slide-up",
  "metric": "count-up",
};

export function Motion({ children, className = "", entrance, delayMs = 0 }: MotionProps) {
  const motionType = entrance ? ENTRANCE_TYPES[entrance] ?? "fade-in" : "fade-in";
  const duration = DEFAULT_DURATION;

  return (
    <div
      className={["v2-motion", className].filter(Boolean).join(" ")}
      data-v2-motion={PRESET}
      data-entrance={motionType}
      style={{
        animation: `${motionType} ${duration}ms cubic-bezier(0.22, 1, 0.36, 1) both`,
        animationDelay: `${delayMs}ms`,
      }}
    >
      {children}
    </div>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Template Architecture V2 — corporate-business · spec 2.0.0 */
:root {
  --v2-package: "corporate-business";
  --color-primary: #0F2B46;
  --color-secondary: #1E4976;
  --color-accent: #2563EB;
  --color-background: #FFFFFF;
  --color-foreground: #0F172A;
  --color-muted: rgba(15,23,42,0.58);
  --color-surface: #F8FAFC;
  --color-signal: #C5A572;
  --color-grid: rgba(15,43,70,0.06);
  --color-ink: #071018;
  --font-display: "IBM Plex Sans", ui-sans-serif, system-ui, sans-serif;
  --font-body: "IBM Plex Sans", ui-sans-serif, system-ui, sans-serif;
  --spacing-unit: 0.25rem;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-surface: 0 1px 2px rgba(15,23,42,0.06), 0 16px 48px rgba(15,43,70,0.08);
  --shadow-glow: 0 0 64px rgba(197,165,114,0.2);
  --shadow-card: 0 0 0 1px rgba(15,43,70,0.05), 0 4px 20px rgba(15,43,70,0.06);
  --border-default: rgba(15,43,70,0.1);
  --border-accent: rgba(37,99,235,0.22);
  --border-subtle: rgba(15,43,70,0.05);
}

/* V2 language profile — RTL typography adaptation */
[dir="rtl"] {
  --font-display: Tajawal, ui-serif, Georgia, serif;
  --font-body: "Noto Sans Arabic", ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.01em;
}

@import url("https://fonts.googleapis.com/css2?family=Cairo:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans+Arabic:wght@400;500;600&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;1,400&family=Plus+Jakarta+Sans:ital,wght@0,500;0,600;0,700;0,800;1,500&display=swap");

@keyframes cb-grid-reveal {
  from { opacity: 0; transform: translateY(20px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes cb-slide-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes cb-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
[dir="rtl"] [class*="se-marquee"],
[dir="rtl"] [class*="cb-marquee"] {
  animation-direction: reverse;
}
@keyframes cb-pulse-dot {
  0%, 100% { opacity: 0.4; transform: scale(0.85); }
  50% { opacity: 1; transform: scale(1); }
}
@keyframes cb-scan-line {
  0% { transform: translateY(-100%); opacity: 0; }
  50% { opacity: 0.06; }
  100% { transform: translateY(100vh); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .cb-animate, [data-cb-motion] { animation: none !important; transition: none !important; }
}

.cb-font-display { font-family: var(--font-display), "IBM Plex Sans", system-ui, sans-serif; }
.cb-font-body { font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif; }
.cb-font-mono { font-family: "IBM Plex Mono", ui-monospace, monospace; }
.cb-eyebrow {
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-accent, #3B82F6);
}
.cb-headline {
  font-family: var(--font-display), "IBM Plex Sans", system-ui, sans-serif;
  font-size: clamp(2.25rem, 4.5vw, 3.75rem);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--color-foreground);
  text-wrap: balance;
}
.cb-headline-sm {
  font-family: var(--font-display), "IBM Plex Sans", system-ui, sans-serif;
  font-size: clamp(1.5rem, 2.8vw, 2.25rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.025em;
  color: var(--color-foreground);
  text-wrap: balance;
}
.cb-body {
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 1.0625rem;
  line-height: 1.65;
  color: var(--color-muted, rgba(15,23,42,0.58));
}
.cb-grid-bg {
  background-image:
    linear-gradient(var(--color-grid, rgba(15,23,42,0.06)) 1px, transparent 1px),
    linear-gradient(90deg, var(--color-grid, rgba(15,23,42,0.06)) 1px, transparent 1px);
  background-size: 48px 48px;
}
.cb-card {
  border: 1px solid var(--border-subtle, rgba(15,23,42,0.04));
  background: var(--color-surface);
  border-radius: var(--radius-lg, 16px);
  box-shadow: var(--shadow-card);
  transition: box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1), transform 0.35s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.35s ease;
}
.cb-card:hover {
  box-shadow: var(--shadow-surface);
  border-color: var(--border-accent, rgba(59,130,246,0.24));
  transform: translateY(-2px);
}
.cb-card-featured {
  border-color: var(--border-accent, rgba(59,130,246,0.28));
  background: linear-gradient(165deg, color-mix(in srgb, var(--color-accent) 5%, var(--color-surface)), var(--color-surface));
  box-shadow: var(--shadow-surface), 0 0 0 1px color-mix(in srgb, var(--color-accent) 12%, transparent);
}
.cb-section-alt {
  background: linear-gradient(180deg, var(--color-surface) 0%, var(--color-background) 100%);
}
.cb-section-glow {
  position: relative;
  isolation: isolate;
}
.cb-section-glow::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 90% 55% at 50% -15%, color-mix(in srgb, var(--color-accent) 9%, transparent), transparent 68%);
}
.cb-glow-orb {
  pointer-events: none;
  position: absolute;
  border-radius: 50%;
  filter: blur(64px);
  opacity: 0.45;
}
.cb-browser-frame {
  border: 1px solid var(--border-default, rgba(15,23,42,0.08));
  border-radius: var(--radius-xl, 20px);
  background: var(--color-surface);
  box-shadow: var(--shadow-surface), 0 0 0 1px color-mix(in srgb, var(--color-accent) 8%, transparent);
  overflow: hidden;
}
.cb-browser-chrome {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  border-bottom: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--color-foreground) 3%, var(--color-surface));
  padding: 0.625rem 0.875rem;
}
.cb-browser-dot {
  height: 0.5rem;
  width: 0.5rem;
  border-radius: 50%;
  background: var(--border-default);
}
.cb-trust-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.25rem 1.75rem;
}
.cb-trust-logo {
  font-family: var(--font-display), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: color-mix(in srgb, var(--color-foreground) 42%, transparent);
  transition: color 0.25s ease;
}
.cb-trust-logo:hover { color: var(--color-foreground); }
.cb-trust-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  border-radius: 9999px;
  border: 1px solid var(--border-default);
  background: color-mix(in srgb, var(--color-surface) 88%, transparent);
  padding: 0.25rem 0.625rem;
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--color-muted);
  backdrop-filter: blur(8px);
}
.cb-star {
  color: var(--color-signal, #059669);
  letter-spacing: 0.12em;
}
.cb-quote-mark {
  font-family: var(--font-display), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 3.5rem;
  line-height: 1;
  color: color-mix(in srgb, var(--color-accent) 35%, transparent);
}
.cb-divider-gradient {
  height: 1px;
  width: 100%;
  background: linear-gradient(90deg, transparent, var(--border-default), transparent);
}
.cb-input,
.cb-textarea {
  width: 100%;
  border-radius: var(--radius-md, 10px);
  border: 1px solid var(--border-default);
  background: var(--color-background);
  padding: 0.625rem 0.875rem;
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.875rem;
  color: var(--color-foreground);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.cb-input:focus-visible,
.cb-textarea:focus-visible {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-accent) 18%, transparent);
}
.cb-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.75rem 1.5rem;
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  color: #fff;
  background: var(--color-primary, #1D4ED8);
  border-radius: var(--radius-md, 10px);
  border: 1px solid transparent;
  box-shadow: 0 1px 2px rgba(15,23,42,0.06);
  transition: background 0.25s ease, box-shadow 0.25s ease, transform 0.2s ease;
}
.cb-btn-primary:hover {
  background: var(--color-accent, #3B82F6);
  box-shadow: var(--shadow-glow);
  transform: translateY(-1px);
}
.cb-btn-primary:active {
  transform: translateY(0) scale(0.98);
}
.cb-btn-primary:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.cb-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.75rem 1.5rem;
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  color: var(--color-foreground);
  background: var(--color-surface);
  border: 1px solid var(--border-default, rgba(15,23,42,0.08));
  border-radius: var(--radius-md, 10px);
  transition: border-color 0.25s ease, background 0.25s ease;
}
.cb-btn-secondary:hover { border-color: var(--color-accent); background: color-mix(in srgb, var(--color-accent) 4%, var(--color-surface)); transform: translateY(-1px); }
.cb-btn-secondary:active { transform: translateY(0) scale(0.98); }
.cb-btn-secondary:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.cb-section { padding-block: clamp(4rem, 10vw, 6.5rem); }
.cb-metric {
  font-family: var(--font-display), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-primary);
}
.cb-signal { color: var(--color-signal, #059669); }
.cb-focus-ring:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.cb-signal { color: var(--color-signal, #C5A572); }
.cb-accent-line {
  height: 3px;
  width: 3rem;
  border-radius: 9999px;
  background: linear-gradient(90deg, var(--color-signal, #C5A572), transparent);
}
.cb-trust-logo {
  font-family: var(--font-display), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--color-foreground) 38%, transparent);
}

/* TBDP Native Consumption — corporate-business
