/* TBDP Experience — motion, interaction, RTL, accessibility */
/* TBDP Phase 3 — Motion System · tbdp-xp */

@keyframes tbdp-xp-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes tbdp-xp-fade-out {
  from { opacity: 1; }
  to { opacity: 0; }
}

@keyframes tbdp-xp-rise {
  from { opacity: 0; transform: translateY(var(--tbdp-spacing-lg)); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes tbdp-xp-rise-rtl {
  from { opacity: 0; transform: translateX(var(--tbdp-spacing-lg)); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes tbdp-xp-scale-in {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes tbdp-xp-slide-end {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

@keyframes tbdp-xp-slide-start {
  from { transform: translateX(-100%); }
  to { transform: translateX(0); }
}

@keyframes tbdp-xp-shake {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(calc(var(--tbdp-spacing-sm) * -1)); }
  40%, 80% { transform: translateX(var(--tbdp-spacing-sm)); }
}

@keyframes tbdp-xp-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.04); }
}

@keyframes tbdp-xp-lift {
  to { transform: translateY(calc(var(--tbdp-spacing-sm) * -1)); box-shadow: var(--tbdp-shadow-2); }
}

@media (prefers-reduced-motion: reduce) {
  [data-tbdp-xp-motion] { animation: none !important; transition: none !important; }
}

[data-tbdp-xp-motion] { will-change: transform, opacity; }
[data-tbdp-xp-motion="page-enter"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="page-exit"] { animation-name: tbdp-xp-fade-out; }
[data-tbdp-xp-motion="section-reveal"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="hero-headline"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="hero-media"] { animation-name: tbdp-xp-scale-in; }
[data-tbdp-xp-motion="card-lift"] { animation-name: tbdp-xp-lift; }
[data-tbdp-xp-motion="grid-stagger"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="modal-enter"] { animation-name: tbdp-xp-scale-in; }
[data-tbdp-xp-motion="modal-exit"] { animation-name: tbdp-xp-fade-out; }
[data-tbdp-xp-motion="drawer-slide"] { animation-name: tbdp-xp-slide-end; }
[data-tbdp-xp-motion="toast-enter"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="toast-exit"] { animation-name: tbdp-xp-fade-out; }
[data-tbdp-xp-motion="tooltip-fade"] { animation-name: tbdp-xp-fade-in; }
[data-tbdp-xp-motion="scroll-reveal-up"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="stagger-children"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="hover-lift"] { animation-name: tbdp-xp-lift; }
[data-tbdp-xp-motion="focus-ring"] { animation-name: tbdp-xp-fade-in; }
[data-tbdp-xp-motion="success-pulse"] { animation-name: tbdp-xp-pulse; }
[data-tbdp-xp-motion="error-shake"] { animation-name: tbdp-xp-shake; }

/* TBDP Experience — interaction utilities */
[data-tbdp-xp] { --tbdp-xp-focus: var(--tbdp-color-border-focus); }
[data-tbdp-xp-feedback="loading"] { cursor: wait; }
[data-tbdp-xp-feedback="error"] { border-color: var(--tbdp-color-danger); }
[data-tbdp-xp-feedback="success"] { border-color: var(--tbdp-color-success); }
[data-tbdp-xp-touch="true"] { min-height: var(--tbdp-spacing-2xl); min-width: var(--tbdp-spacing-2xl); }
[data-tbdp-xp-gpu] { transform: translateZ(0); backface-visibility: hidden; }
[data-tbdp-xp-contain] { content-visibility: auto; contain-intrinsic-size: auto 500px; }

@media (prefers-reduced-motion: reduce) {
  [data-tbdp-xp], [data-tbdp-xp-motion] { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}
/* V2 sidebar-left layout */
.v2-layout-sidebar-left .v2-sidebar-shell { gap: 0; align-items: flex-start; }
.v2-sidebar-rail {
  border-inline-end: 1px solid var(--border-subtle, rgba(244,237,228,0.06));
  padding-block: clamp(2rem, 5vw, 3.5rem);
  padding-inline-end: clamp(1.25rem, 3vw, 2rem);
}
[dir='rtl'] .v2-sidebar-rail { border-inline-end: none; border-inline-start: 1px solid var(--border-subtle, rgba(244,237,228,0.06)); }
.v2-main-canvas > [data-v2-component] + [data-v2-component] { margin-top: 0; }
.v2-layout-sidebar-left .v2-main-canvas { padding-inline-start: 0; }
@media (max-width: 1023px) {
  .v2-sidebar-rail { display: none !important; }
}

/* V2 sidebar-right layout */
.v2-layout-sidebar-right .v2-sidebar-shell { gap: 0; align-items: flex-start; }
.v2-layout-sidebar-right .v2-sidebar-rail {
  border-inline-start: 1px solid var(--border-subtle, rgba(28,25,23,0.06));
  border-inline-end: none;
  padding-block: clamp(2rem, 5vw, 3.5rem);
  padding-inline-start: clamp(1.25rem, 3vw, 2rem);
}
[dir='rtl'] .v2-layout-sidebar-right .v2-sidebar-rail {
  border-inline-start: none;
  border-inline-end: 1px solid var(--border-subtle, rgba(28,25,23,0.06));
}

/* V2 full-bleed layout */
.v2-layout-full-bleed .v2-overlay-canvas { width: 100%; }
.v2-layout-full-bleed .v2-main-canvas { width: 100%; max-width: var(--container-max, 76rem); margin-inline: auto; }

/* V2 editorial-reveal layout (creative portfolio) */
.v2-layout-editorial-reveal .v2-main-canvas { width: 100%; }
.v2-layout-editorial-reveal .v2-overlay-reveal { width: 100%; }

