      className="cb-section se-section-glow relative min-h-[min(92vh,56rem)] overflow-hidden bg-[var(--color-background)] py-16 sm:py-20 lg:py-24"
    >
      <div className="cb-grid-bg pointer-events-none absolute inset-0 opacity-45" aria-hidden />
      <div className="se-glow-orb start-0 top-0 h-64 w-64 bg-[var(--color-signal)]" aria-hidden />
      <div
        className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_65%_45%_at_90%_10%,rgba(197,165,114,0.16),transparent_55%)]"
        aria-hidden
      />

      <div className="relative mx-auto max-w-[82rem] px-5 sm:px-8">
        <div className="grid gap-12 lg:grid-cols-[1.05fr_0.95fr] lg:items-center lg:gap-16">
          <div className="max-w-xl">
            <p className="cb-eyebrow mb-4 motion-safe:animate-[cb-slide-up_0.6s_ease_both]">{eyebrow}</p>
            <div className="cb-accent-line mb-6 motion-safe:animate-[cb-slide-up_0.6s_ease_0.04s_both]" aria-hidden />
            <h1
              id="cb-hero-title"
              className="cb-headline motion-safe:animate-[cb-slide-up_0.65s_ease_0.08s_both]"
            >
              {title}
            </h1>
            <p className="cb-body text-muted-foreground mt-6 max-w-lg motion-safe:animate-[cb-slide-up_0.65s_ease_0.16s_both]">
              {subtitle}
            </p>
            <div className="mt-9 flex flex-wrap gap-3 motion-safe:animate-[cb-slide-up_0.65s_ease_0.24s_both]">
              <a href="#contact" className="cb-btn-primary cb-focus-ring">
                {primaryCta}
              </a>
              <a href="#features" className="cb-btn-secondary cb-focus-ring">
                {secondaryCta}
              </a>
            </div>
            <div className="mt-10 space-y-5 motion-safe:animate-[cb-slide-up_0.65s_ease_0.32s_both]">
              <div className="flex flex-wrap items-center gap-3">
                <span className="se-trust-badge">
                  <span className="h-1.5 w-1.5 rounded-full bg-[var(--color-signal)]" aria-hidden />
                  Trusted advisory partner
                </span>
                <span className="cb-font-body text-xs text-[var(--color-muted)]">
                  Fortune 500 · ISO 9001 · Global reach
                </span>
              </div>
              <div>
                <p className="cb-font-body mb-3 text-[0.625rem] font-semibold uppercase tracking-[0.14em] text-[var(--color-muted)]">
                  Advising leaders at
                </p>
                <div className="se-trust-strip" aria-label="Trusted by global enterprises">
                  {TRUST_BRANDS.map((brand) => (
                    <span key={brand} className="cb-trust-logo">
                      {brand}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="motion-safe:animate-[cb-grid-reveal_0.85s_ease_0.15s_both]">
            <div className="cb-card overflow-hidden p-1.5 shadow-[var(--shadow-surface)]">
              <img
                src={src}
                alt="Executive leadership team in a strategy session at a global headquarters"
                className="aspect-[4/3] w-full rounded-[calc(var(--radius-lg)-4px)] object-cover"
                fetchPriority="high"
              />
            </div>
            <div className="mt-4 grid grid-cols-2 gap-3">
              {metrics.map((metric, i) => (
                <div
                  key={metric.label}
                  className="cb-card p-4 motion-safe:animate-[cb-grid-reveal_0.6s_ease_both]"
                  style={{ animationDelay: `${0.35 + i * 0.07}s` }}
                >
                  <p className="cb-metric text-2xl">{metric.value}</p>
                  <p className="cb-font-body mt-1 text-[0.6875rem] text-[var(--color-muted)]">{metric.label}</p>
                  {metric.trend ? (
                    <p className="cb-font-mono mt-0.5 text-[0.625rem] text-[var(--color-signal)]">{metric.trend}</p>
                  ) : null}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

